import math

def cross_entropy_from_logits(logits_batch, targets):
    total = 0.0
    for row, t in zip(logits_batch, targets):
        m = max(row)
        exps = [math.exp(z - m) for z in row]
        p_t = exps[t] / sum(exps)
        total += -math.log(p_t)
    return total / len(targets)
